/* import React from "react"
import {useLocation, useNavigate} from 'react-router-dom';

function Home (){
    const location=useLocation()

    return (
        <div className="homepage">

            <h1>Hello {location.state.id} and welcome to the home</h1>

        </div>
    )
}

export default Home */

import React from 'react';
import LoginForm from './LoginForm';
import './MainPage.css';

function MainPage() {
  return (
    <div className="App">
      {/* Our Services Section */}
      <section className="services-section">
        <h2>Our Services</h2>
        <div className="services">
          <div className="service-card">
            <span className="icon">🐖</span>
            <h3>Savings Account</h3>
            <p>Grow your wealth securely with our high-interest savings accounts.</p>
          </div>
          <div className="service-card">
            <span className="icon">💳</span>
            <h3>Credit Cards</h3>
            <p>Flexible credit card options with rewards and cashback offers.</p>
          </div>
          <div className="service-card">
            <span className="icon">📈</span>
            <h3>Investment Plans</h3>
            <p>Strategic investment solutions to help you achieve your financial goals.</p>
          </div>
        </div>
      </section>

      {/* Login Section */}
      <section className="login-section">
        <h2>Existing User Login</h2>
        <form className="login-form">
          <input type="email" placeholder="Email" />
          <input type="password" placeholder="Password" />
          <button type="submit">Log In</button>
        </form>
      </section>

      {/* Footer */}
      <footer>
        <div className="footer-links">
          <a href="#privacy">Privacy Policy</a>
          <a href="#terms">Terms of Service</a>
          <a href="#help">Help Center</a>
        </div>
        <p>©️ 2024 Digibank all rights reserved</p>
      </footer>
    </div>

  );
}

export default MainPage;
